html:
{%- set m = frappe.get_doc("Plan Member", doc.member) -%}
{%- set plan = frappe.db.get_value("Health Plan", m.plan, ["plan_name", "plan_name_ar", "tpa_client"], as_dict=True) -%}
{%- set rtl = frappe.local.lang == "ar" -%}
{%- set qr = card_qr(doc.name) -%}
<style>
@page { size: 85.6mm 54mm; margin: 0; }
html, body { margin: 0; padding: 0; background: #fff; }
.mc, .mc * { box-sizing: border-box; }
.mc { width: 85.6mm; height: 54mm; position: relative; overflow: hidden; page-break-after: always; color: #fff; padding: 5mm 5.5mm;
  font-family: -apple-system, "SF Pro Text", "Segoe UI", "Helvetica Neue", Tahoma, Arial, sans-serif; border-radius: 3.2mm;
  background: linear-gradient(135deg, #0a1f44 0%, #123a73 58%, #2a7fb8 100%); }
.mc::before { content: ""; position: absolute; width: 60mm; height: 60mm; border-radius: 50%; top: -32mm; inset-inline-end: -22mm; background: rgba(255,255,255,.07); }
.mc::after { content: ""; position: absolute; width: 46mm; height: 46mm; border-radius: 50%; bottom: -30mm; inset-inline-start: -14mm; background: rgba(255,255,255,.05); }
.mc .top { display: flex; justify-content: space-between; align-items: flex-start; position: relative; z-index: 1; }
.mc .brand { font-size: 3.1mm; font-weight: 600; letter-spacing: .02em; opacity: .92; }
.mc .kind { font-size: 2.3mm; opacity: .7; margin-top: .6mm; }
.mc .chip { width: 8.5mm; height: 6.2mm; border-radius: 1.3mm; background: linear-gradient(135deg, #f4d58d, #c79a3b); opacity: .95; }
.mc .name { position: relative; z-index: 1; margin-top: 6mm; font-size: 4.6mm; font-weight: 600; letter-spacing: .005em; line-height: 1.15; }
.mc .no { position: relative; z-index: 1; margin-top: 1.4mm; font-size: 3.4mm; letter-spacing: .14em; font-variant-numeric: tabular-nums; direction: ltr; text-align: start; opacity: .95; }
.mc .meta { position: absolute; z-index: 1; bottom: 4.6mm; inset-inline-start: 5.5mm; display: flex; gap: 5mm; }
.mc .meta div span { display: block; font-size: 1.9mm; text-transform: uppercase; letter-spacing: .08em; opacity: .62; }
.mc .meta div b { display: block; font-size: 2.8mm; font-weight: 600; margin-top: .4mm; }
.mc .qr { position: absolute; z-index: 1; bottom: 4.2mm; inset-inline-end: 5mm; width: 15.5mm; height: 15.5mm; padding: 1mm; border-radius: 2mm; background: #fff; }
.mc .qr img { width: 100%; height: 100%; display: block; }
.back { background: #f5f7fa; color: #1c2b3a; }
.back::before, .back::after { display: none; }
.back h4 { margin: 0 0 2mm; font-size: 3.1mm; font-weight: 600; }
.back p { margin: 0 0 1.4mm; font-size: 2.35mm; line-height: 1.5; color: #44546a; }
.back .strip { position: absolute; inset-inline: 0; bottom: 0; height: 7mm; background: #0a1f44; color: #fff; font-size: 2.3mm; display: flex; align-items: center; justify-content: center; letter-spacing: .04em; }
</style>
<div class="mc" dir="{{ 'rtl' if rtl else 'ltr' }}">
  <div class="top">
    <div><div class="brand">{{ (plan.plan_name_ar if rtl and plan.plan_name_ar else plan.plan_name) }}</div><div class="kind">{{ _("Health Insurance Card") }}</div></div>
    <div class="chip"></div>
  </div>
  <div class="name">{{ (m.member_name_ar if rtl and m.member_name_ar else m.member_name) }}</div>
  <div class="no">{{ doc.card_no }}</div>
  <div class="meta">
    {% if m.class_name %}<div><span>{{ _("Class") }}</span><b>{{ m.class_name }}</b></div>{% endif %}
    <div><span>{{ _("Valid Until") }}</span><b>{{ doc.get_formatted("valid_until") if doc.valid_until else "-" }}</b></div>
  </div>
  <div class="qr"><img src="{{ qr }}" alt=""></div>
</div>
<div class="mc back" dir="{{ 'rtl' if rtl else 'ltr' }}">
  <h4>{{ _("How to use this card") }}</h4>
  <p>{{ _("Present this card with an official ID at the provider before receiving any service.") }}</p>
  <p>{{ _("The provider scans the QR code to confirm that the membership is active today.") }}</p>
  <p>{{ _("Some services need a pre-authorization before treatment. Ask the provider to request it.") }}</p>
  <p>{{ _("This card is personal and cannot be transferred. Report a lost card immediately.") }}</p>
  <div class="strip">{{ doc.card_no }}</div>
</div>
